function GordonAccordion() {
  const [openIdx, setOpenIdx] = React.useState(null);

  return (
    React.createElement('div', { style: { marginTop: 36, display: 'flex', flexDirection: 'column', gap: 10 } },
      gordonSections.map(function(section, i) {
        return React.createElement('div', {
          key: i,
          style: { border: '1.5px solid #e5e7eb', borderRadius: 8, overflow: 'hidden', background: '#f9fafb' }
        },
          React.createElement('button', {
            onClick: function() { setOpenIdx(openIdx === i ? null : i); },
            style: {
              width: '100%', display: 'flex', alignItems: 'center',
              justifyContent: 'space-between', padding: '14px 18px',
              background: 'none', border: 'none', cursor: 'pointer', textAlign: 'left', gap: 12,
            }
          },
            React.createElement('span', {
              style: { fontSize: 15, fontWeight: 700, color: '#4B5563', letterSpacing: '0.04em', lineHeight: 1.4 }
            }, section.title),
            React.createElement('div', {
              style: {
                width: 28, height: 28, borderRadius: '50%', background: '#ff0000', flexShrink: 0,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                color: 'white', fontSize: 18, fontWeight: 700,
                transition: 'transform 0.2s',
                transform: openIdx === i ? 'rotate(45deg)' : 'rotate(0deg)',
              }
            }, '+')
          ),
          openIdx === i && React.createElement('div', {
            style: { padding: '4px 18px 18px', borderTop: '1px solid #e5e7eb' }
          },
            section.content.map(function(para, pi) {
              return React.createElement('p', {
                key: pi,
                style: { fontSize: 17, color: '#374151', lineHeight: 1.85, marginBottom: 14, fontFamily: 'monserrat, monserrat' }
              }, para);
            })
          )
        );
      })
    )
  );
}

